# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KİTAP FUARINDA (فِي مَعْرِضِ الْكِتَابِ) UYGULAMALARI VE BETİMLEMELER</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Fuar Soru ve Cevap Kalıpları</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">إِلَى أَيْنَ تَذْهَبُ؟ ➔ إِلَى مَعْرِضِ الْكِتَابِ</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#334155">Nereye gidiyorsun? ➔ Kitap fuarına</text>\n  <text x="180" y="142" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">مَعَ مَنْ تَذْهَبُ؟ ➔ مَعَ أُسْرَتِي / أَصْدِقَائِي</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11" fill="#334155">Kiminle gidiyorsun? ➔ Ailemle / Arkadaşlarımla</text>\n  <text x="180" y="188" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">مَتَى تَذْهَبُ؟ ➔ فِي يَوْمِ السَّبْتِ</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" fill="#334155">Ne zaman gidiyorsun? ➔ Cumartesi günü</text>\n  <text x="180" y="228" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">أَيَّ كِتَابٍ تُفَضِّلُ؟ (Hangi kitabı tercih edersin?)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Betimleyici İfadeler ve Özdeyişler</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">اَلْأَعْمَالُ الْيَدَوِيَّةُ مُمْتِعَةٌ (El sanatları eğlencelidir)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">اَلْخَطُّ الْعَرَبِيُّ سَهْلٌ وَجَمِيلٌ (Hüsn-i hat kolay ve güzeldir)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">تَسْقُطُ أَوْرَاقُ الْأَشْجَارِ (Ağaçların yaprakları dökülür)</text>\n  <text x="520" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">مَنْ لَا يَعْمَلُ لَا يُنْتِجُ</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#334155">Çalışmayan üretmez.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">اَلْعَمَلُ خَيْرٌ مِنَ التَّسَوُّلِ (Çalışmak dilenmekten hayırlıdır)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİNEMA VE TİYATRO (السِّينَمَا وَالْمَسْرَحُ) KAVRAMLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Temel Kelimeler (الْمُفْرَدَاتُ)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">السِّينَمَا (Sinema) | الْمَسْرَحُ (Tiyatro sahnesi)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">فِيلْمٌ (Film) | مَسْرَحِيَّةٌ (Tiyatro oyunu)</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">مُمَثِّلٌ / مُمَثِّلَةٌ (Erkek / Kadın oyuncu)</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">تَذْكِرَةٌ (Bilet) | شُبَّاكُ التَّذَاكِرِ (Bilet gişesi)</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">مُخْرِجٌ (Yönetmen) | دَوْرٌ (Rol)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#713f12">مُشَاهِدٌ / جُمْهُورٌ (İzleyici / Seyirci kitlesi)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Film ve Oyun Türleri (أَنْوَاعُ الْأَفْلَامِ)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">فِيلْمٌ تَارِيخِيٌّ (Tarihî film)</text>\n  <text x="520" y="126" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">فِيلْمٌ وَثَائِقِيٌّ (Belgesel film)</text>\n  <text x="520" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">فِيلْمٌ كُومِيدِيٌّ / فُكَاهِيٌّ (Komedi filmi)</text>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">أَفْلَامُ الرُّسُومِ الْمُتَحَرِّكَةِ (Çizgi filmler / Animasyon)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#475569">مَسْرَحِيَّةٌ هَادِفَةٌ (Eğitici / mesaj veren tiyatro oyunu)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİNEMA VE TİYATRO DİYALOGLARI İLE ZAMAN BAĞLAÇLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Gişe ve Davet İfadeleri</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">هَيَّا نَذْهَبْ إِلَى الْمَسْرَحِ! (Haydi tiyatroya gidelim!)</text>\n  <text x="180" y="126" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">أُرِيدُ تَذْكِرَتَيْنِ مِنْ فَضْلِكَ (Lütfen iki bilet istiyorum)</text>\n  <text x="180" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">مَتَى يَبْدَأُ الْعَرْضُ؟ (Gösterim ne zaman başlıyor?)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">يَبْدَأُ الْعَرْضُ فِي السَّاعَةِ السَّابِعَةِ (Saat yedide başlıyor)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#881337">كَمْ سِعْرُ التَّذْكِرَةِ؟ (Biletin fiyatı ne kadar?)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Olay Sıralama (Ardışıklık) Bağlaçları</text>\n  <text x="520" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">1. أَوَّلًا: نَشْتَرِي التَّذْكِرَةَ (Önce bileti satın alırız)</text>\n  <text x="520" y="126" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">2. قَبْلَ الْعَرْضِ: نَدْخُلُ الصَّالَةَ (Gösterimden önce salona gireriz)</text>\n  <text x="520" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">3. ثُمَّ: نُشَاهِدُ الْمَسْرَحِيَّةَ (Sonra oyunu izleriz)</text>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">4. بَعْدَ الْعَرْضِ: نَخْرُجُ مَسْرُورِينَ (Gösterimden sonra mutlu çıkarız)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#0f172a">Bağlaçlar: وَ (ve) · ثُمَّ (sonra) · قَبْلَ (önce) · بَعْدَ (sonra)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
